import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    X = []
    for _ in range(K):
        X.append(int(next(iterator)))

    try:
        Q = int(next(iterator))
    except StopIteration:
        return

    queries = []
    for _ in range(Q):
        l = int(next(iterator))
        r = int(next(iterator))
        queries.append((l, r))

    # Precompute prefix sums of occurrences
    # occ[i] will store how many times index i was incremented
    occ = [0] * N
    for jump in X:
        if jump == 0:
            continue
        for i in range(jump, N, jump):
            occ[i] += 1

    # Build prefix sum array for fast range sum queries
    pref = [0] * (N + 1)
    current_sum = 0
    for i in range(N):
        current_sum += occ[i]
        pref[i+1] = current_sum

    results = []
    for l, r in queries:
        total = pref[r+1] - pref[l]
        results.append(str(total))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
